function maximumProduct(nums) {
  let best = -Infinity;
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++)
      for (let k = j + 1; k < nums.length; k++) {
        const product = nums[i] * nums[j] * nums[k];
        if (product > best) best = product;
      }
  return best;
}

