function generate(rand, size) {
  if (size === 'large') {
    const n = 1500 + Math.floor(rand() * 501);
    return [Array.from({ length: n }, () => Math.floor(rand() * 2001) - 1000)];
  }
  const n = 3 + Math.floor(rand() * 8);
  const mode = rand();
  let pick;
  if (mode < 0.2) pick = () => -1 - Math.floor(rand() * 10);
  else if (mode < 0.35) pick = () => (rand() < 0.5 ? -1000 : 1000) * (rand() < 0.7 ? 1 : 0);
  else pick = () => Math.floor(rand() * 21) - 10;
  return [Array.from({ length: n }, pick)];
}
